func warnDeprecatedAliasOnce(cmd *cobra.Command, oldUse, replacement string) {
	old := firstWord(oldUse)
	if old == "" {
		old = cmd.Name()
	}
	key := old + "->" + replacement
	val, _ := deprecationWarnOnce.LoadOrStore(key, &sync.Once{})
	once, ok := val.(*sync.Once)
	if !ok {
